CREATE TABLE IF NOT EXISTS `sf2_projects` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `sourceFilePath` TEXT, `isLegacyProject` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `modifiedAt` INTEGER NOT NULL)
CREATE TABLE IF NOT EXISTS `sf2_programs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `projectId` INTEGER NOT NULL, `name` TEXT NOT NULL, `programNumber` INTEGER NOT NULL, `bankNumber` INTEGER NOT NULL, `globalAttenuation` INTEGER NOT NULL, `globalCoarseTune` INTEGER NOT NULL, `globalFineTune` INTEGER NOT NULL, `globalVolEnvDelay` INTEGER NOT NULL, `globalVolEnvAttack` INTEGER NOT NULL, `globalVolEnvHold` INTEGER NOT NULL, `globalVolEnvDecay` INTEGER NOT NULL, `globalVolEnvSustain` INTEGER NOT NULL, `globalVolEnvRelease` INTEGER NOT NULL, `globalModEnvDelay` INTEGER NOT NULL, `globalModEnvAttack` INTEGER NOT NULL, `globalModEnvHold` INTEGER NOT NULL, `globalModEnvDecay` INTEGER NOT NULL, `globalModEnvSustain` INTEGER NOT NULL, `globalModEnvRelease` INTEGER NOT NULL, `globalModEnvToPitch` INTEGER NOT NULL, `globalModEnvToFilterFc` INTEGER NOT NULL, `globalVibLfoDelay` INTEGER NOT NULL, `globalVibLfoFreq` INTEGER NOT NULL, `globalVibLfoToPitch` INTEGER NOT NULL, `globalModLfoDelay` INTEGER NOT NULL, `globalModLfoFreq` INTEGER NOT NULL, `globalModLfoToPitch` INTEGER NOT NULL, `globalModLfoToFilterFc` INTEGER NOT NULL, `globalModLfoToVolume` INTEGER NOT NULL, `globalFilterFc` INTEGER NOT NULL, `globalFilterQ` INTEGER NOT NULL, `globalChorusSend` INTEGER NOT NULL, `globalReverbSend` INTEGER NOT NULL, `globalPan` INTEGER NOT NULL, `globalKeyToModEnvHold` INTEGER NOT NULL, `globalKeyToModEnvDecay` INTEGER NOT NULL, `globalKeyToVolEnvHold` INTEGER NOT NULL, `globalKeyToVolEnvDecay` INTEGER NOT NULL, `globalScaleTuning` INTEGER NOT NULL, `globalExclusiveClass` INTEGER NOT NULL, FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_programs_projectId` ON `sf2_programs` (`projectId`)
CREATE TABLE IF NOT EXISTS `sf2_presets` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `projectId` INTEGER NOT NULL, `name` TEXT NOT NULL, `programId` INTEGER, `instrumentId` INTEGER NOT NULL, `programNumber` INTEGER NOT NULL, `bankNumber` INTEGER NOT NULL, `pgenKeyRangeLow` INTEGER NOT NULL, `pgenKeyRangeHigh` INTEGER NOT NULL, `pgenVelRangeLow` INTEGER NOT NULL, `pgenVelRangeHigh` INTEGER NOT NULL, `pgenAttenuation` INTEGER NOT NULL, `pgenCoarseTune` INTEGER NOT NULL, `pgenFineTune` INTEGER NOT NULL, `pgenFilterFc` INTEGER NOT NULL, `pgenFilterQ` INTEGER NOT NULL, `pgenChorusSend` INTEGER NOT NULL, `pgenReverbSend` INTEGER NOT NULL, `pgenPan` INTEGER NOT NULL, `pgenVolEnvDelay` INTEGER NOT NULL, `pgenVolEnvAttack` INTEGER NOT NULL, `pgenVolEnvHold` INTEGER NOT NULL, `pgenVolEnvDecay` INTEGER NOT NULL, `pgenVolEnvSustain` INTEGER NOT NULL, `pgenVolEnvRelease` INTEGER NOT NULL, `pgenModEnvDelay` INTEGER NOT NULL, `pgenModEnvAttack` INTEGER NOT NULL, `pgenModEnvHold` INTEGER NOT NULL, `pgenModEnvDecay` INTEGER NOT NULL, `pgenModEnvSustain` INTEGER NOT NULL, `pgenModEnvRelease` INTEGER NOT NULL, `pgenModEnvToPitch` INTEGER NOT NULL, `pgenModEnvToFilterFc` INTEGER NOT NULL, `pgenVibLfoDelay` INTEGER NOT NULL, `pgenVibLfoFreq` INTEGER NOT NULL, `pgenVibLfoToPitch` INTEGER NOT NULL, `pgenModLfoDelay` INTEGER NOT NULL, `pgenModLfoFreq` INTEGER NOT NULL, `pgenModLfoToPitch` INTEGER NOT NULL, `pgenModLfoToFilterFc` INTEGER NOT NULL, `pgenModLfoToVolume` INTEGER NOT NULL, `pgenKeyToModEnvHold` INTEGER NOT NULL, `pgenKeyToModEnvDecay` INTEGER NOT NULL, `pgenKeyToVolEnvHold` INTEGER NOT NULL, `pgenKeyToVolEnvDecay` INTEGER NOT NULL, `pgenScaleTuning` INTEGER NOT NULL, `pgenExclusiveClass` INTEGER NOT NULL, `originalStateHash` TEXT, `isModifiedByUser` INTEGER NOT NULL, `modificationFlags` INTEGER NOT NULL, FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`programId`) REFERENCES `sf2_programs`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL , FOREIGN KEY(`instrumentId`) REFERENCES `sf2_instruments`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_presets_projectId` ON `sf2_presets` (`projectId`)
CREATE INDEX IF NOT EXISTS `index_sf2_presets_programId` ON `sf2_presets` (`programId`)
CREATE INDEX IF NOT EXISTS `index_sf2_presets_instrumentId` ON `sf2_presets` (`instrumentId`)
CREATE TABLE IF NOT EXISTS `sf2_instruments` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `projectId` INTEGER NOT NULL, `name` TEXT NOT NULL, `globalAttenuation` INTEGER NOT NULL, `globalCoarseTune` INTEGER NOT NULL, `globalFineTune` INTEGER NOT NULL, `globalVolEnvDelay` INTEGER NOT NULL, `globalVolEnvAttack` INTEGER NOT NULL, `globalVolEnvHold` INTEGER NOT NULL, `globalVolEnvDecay` INTEGER NOT NULL, `globalVolEnvSustain` INTEGER NOT NULL, `globalVolEnvRelease` INTEGER NOT NULL, `globalModEnvDelay` INTEGER NOT NULL, `globalModEnvAttack` INTEGER NOT NULL, `globalModEnvHold` INTEGER NOT NULL, `globalModEnvDecay` INTEGER NOT NULL, `globalModEnvSustain` INTEGER NOT NULL, `globalModEnvRelease` INTEGER NOT NULL, `globalModEnvToPitch` INTEGER NOT NULL, `globalModEnvToFilterFc` INTEGER NOT NULL, `globalVibLfoDelay` INTEGER NOT NULL, `globalVibLfoFreq` INTEGER NOT NULL, `globalVibLfoToPitch` INTEGER NOT NULL, `globalModLfoDelay` INTEGER NOT NULL, `globalModLfoFreq` INTEGER NOT NULL, `globalModLfoToPitch` INTEGER NOT NULL, `globalModLfoToFilterFc` INTEGER NOT NULL, `globalModLfoToVolume` INTEGER NOT NULL, `globalFilterFc` INTEGER NOT NULL, `globalFilterQ` INTEGER NOT NULL, `globalChorusSend` INTEGER NOT NULL, `globalReverbSend` INTEGER NOT NULL, `globalPan` INTEGER NOT NULL, `globalKeyToModEnvHold` INTEGER NOT NULL, `globalKeyToModEnvDecay` INTEGER NOT NULL, `globalKeyToVolEnvHold` INTEGER NOT NULL, `globalKeyToVolEnvDecay` INTEGER NOT NULL, `globalScaleTuning` INTEGER NOT NULL, `globalExclusiveClass` INTEGER NOT NULL, `originalStateHash` TEXT, `isModifiedByUser` INTEGER NOT NULL, `modificationFlags` INTEGER NOT NULL, FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_instruments_projectId` ON `sf2_instruments` (`projectId`)
CREATE TABLE IF NOT EXISTS `sf2_samples` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `instrumentId` INTEGER NOT NULL, `name` TEXT NOT NULL, `audioFilePath` TEXT NOT NULL, `sampleRate` INTEGER NOT NULL, `rootNote` INTEGER NOT NULL, `keyRangeStart` INTEGER NOT NULL, `keyRangeEnd` INTEGER NOT NULL, `velRangeStart` INTEGER NOT NULL, `velRangeEnd` INTEGER NOT NULL, `loopStart` INTEGER NOT NULL, `loopEnd` INTEGER NOT NULL, `hasLoop` INTEGER NOT NULL, `sampleModes` INTEGER NOT NULL, `attenuation` INTEGER NOT NULL, `coarseTune` INTEGER NOT NULL, `fineTuneCents` INTEGER NOT NULL, `scaleTuning` INTEGER NOT NULL, `volEnvDelay` INTEGER NOT NULL, `volEnvAttack` INTEGER NOT NULL, `volEnvHold` INTEGER NOT NULL, `volEnvDecay` INTEGER NOT NULL, `volEnvSustain` INTEGER NOT NULL, `volEnvRelease` INTEGER NOT NULL, `modEnvDelay` INTEGER NOT NULL, `modEnvAttack` INTEGER NOT NULL, `modEnvHold` INTEGER NOT NULL, `modEnvDecay` INTEGER NOT NULL, `modEnvSustain` INTEGER NOT NULL, `modEnvRelease` INTEGER NOT NULL, `modEnvToPitch` INTEGER NOT NULL, `modEnvToFilterFc` INTEGER NOT NULL, `vibLfoDelay` INTEGER NOT NULL, `vibLfoFreq` INTEGER NOT NULL, `vibLfoToPitch` INTEGER NOT NULL, `modLfoDelay` INTEGER NOT NULL, `modLfoFreq` INTEGER NOT NULL, `modLfoToPitch` INTEGER NOT NULL, `modLfoToFilterFc` INTEGER NOT NULL, `modLfoToVolume` INTEGER NOT NULL, `filterFc` INTEGER NOT NULL, `filterQ` INTEGER NOT NULL, `chorusSend` INTEGER NOT NULL, `reverbSend` INTEGER NOT NULL, `pan` INTEGER NOT NULL, `exclusiveClass` INTEGER NOT NULL, `keyToVolEnvHold` INTEGER NOT NULL, `keyToVolEnvDecay` INTEGER NOT NULL, `keyToModEnvHold` INTEGER NOT NULL, `keyToModEnvDecay` INTEGER NOT NULL, `fixedKey` INTEGER NOT NULL, `fixedVelocity` INTEGER NOT NULL, `pitchCorrection` INTEGER NOT NULL, `sourceFilePath` TEXT, `sourceSmplOffset` INTEGER NOT NULL, `sourceSampleSize` INTEGER NOT NULL, `isExtracted` INTEGER NOT NULL, `originalStateHash` TEXT, `isModifiedByUser` INTEGER NOT NULL, `modificationFlags` INTEGER NOT NULL, FOREIGN KEY(`instrumentId`) REFERENCES `sf2_instruments`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_samples_instrumentId` ON `sf2_samples` (`instrumentId`)
CREATE TABLE IF NOT EXISTS `sf2_modulators` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `programId` INTEGER, `presetId` INTEGER, `instrumentId` INTEGER, `sampleId` INTEGER, `srcOper` INTEGER NOT NULL, `destOper` INTEGER NOT NULL, `amount` INTEGER NOT NULL, `amtSrcOper` INTEGER NOT NULL, `transOper` INTEGER NOT NULL, FOREIGN KEY(`programId`) REFERENCES `sf2_programs`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`presetId`) REFERENCES `sf2_presets`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`instrumentId`) REFERENCES `sf2_instruments`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`sampleId`) REFERENCES `sf2_samples`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_modulators_programId` ON `sf2_modulators` (`programId`)
CREATE INDEX IF NOT EXISTS `index_sf2_modulators_presetId` ON `sf2_modulators` (`presetId`)
CREATE INDEX IF NOT EXISTS `index_sf2_modulators_instrumentId` ON `sf2_modulators` (`instrumentId`)
CREATE INDEX IF NOT EXISTS `index_sf2_modulators_sampleId` ON `sf2_modulators` (`sampleId`)
CREATE TABLE IF NOT EXISTS `sf2_source_metadata` (`projectId` INTEGER NOT NULL, `sourceFilePath` TEXT, `sourceFileHash` TEXT, `chunkRegistry` TEXT NOT NULL, `sampleIndexMapping` TEXT NOT NULL, `importedAt` INTEGER NOT NULL, PRIMARY KEY(`projectId`), FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE TABLE IF NOT EXISTS `sf2_patches` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `projectId` INTEGER NOT NULL, `targetType` TEXT NOT NULL, `targetIndex` INTEGER NOT NULL, `patchType` TEXT NOT NULL, `patchData` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_patches_projectId` ON `sf2_patches` (`projectId`)
CREATE INDEX IF NOT EXISTS `index_sf2_patches_targetType` ON `sf2_patches` (`targetType`)
CREATE INDEX IF NOT EXISTS `index_sf2_patches_targetIndex` ON `sf2_patches` (`targetIndex`)
CREATE TABLE IF NOT EXISTS `sf2_index` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `projectId` INTEGER NOT NULL, `elementType` TEXT NOT NULL, `originalIndex` INTEGER NOT NULL, `name` TEXT NOT NULL, `programNumber` INTEGER, `bankNumber` INTEGER, `rootNote` INTEGER, `sampleRate` INTEGER, `isDeleted` INTEGER NOT NULL, `isAdded` INTEGER NOT NULL, FOREIGN KEY(`projectId`) REFERENCES `sf2_projects`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_sf2_index_projectId` ON `sf2_index` (`projectId`)
CREATE INDEX IF NOT EXISTS `index_sf2_index_elementType` ON `sf2_index` (`elementType`)
CREATE INDEX IF NOT EXISTS `index_sf2_index_originalIndex` ON `sf2_index` (`originalIndex`)